import time
from fractions import Fraction


class TokenBucket:
    """A continuously refilled token bucket."""

    def __init__(self, rate, capacity, clock=time.monotonic):
        if not (rate > 0 and capacity > 0):
            raise ValueError("rate and capacity must be positive")
        self._rate = rate if isinstance(rate, float) else Fraction(rate)
        self._capacity = capacity
        self._tokens = capacity
        self._clock = clock
        self._last = clock()

    def available(self):
        now = self._clock()
        elapsed = now - self._last
        self._last = now
        if elapsed > 0:
            self._tokens = min(self._capacity, self._tokens + self._rate * elapsed)
        return self._tokens

    def _validate_cost(self, cost):
        if not 0 < cost <= self._capacity:
            raise ValueError("cost must be positive and at most capacity")

    def take(self, cost=1):
        self._validate_cost(cost)
        if self.available() < cost:
            return False
        self._tokens -= cost
        return True

    def wait_time(self, cost=1):
        self._validate_cost(cost)
        deficit = cost - self.available()
        return deficit / self._rate if deficit > 0 else 0
